1	import Phaser from 'phaser';
2	import { AUDIO } from '../config/gameConfig';
3	
4	/**
5	 * audio.ts — placeholder SFX + music, 100% static-hostable with NO external
6	 * files or network. Sounds are SYNTHESIZED at runtime (simple Web Audio-style
7	 * oscillator maths) into 16-bit PCM WAV blobs, then handed to Phaser's normal
8	 * loader (`load.audio`). Playback goes through the scene's shared sound manager,
9	 * so the persisted mute + iOS unlock owned by AudioManager apply automatically —
10	 * this module never touches mute state itself.
11	 *
12	 * Phase 5 can drop in real assets by replacing `registerAudio()` with real
13	 * `loader.audio(key, ['x.m4a','x.ogg'])` calls under the same keys; nothing else
14	 * needs to change.
15	 */
16	
17	// ── Sound keys ───────────────────────────────────────────────────────────────
18	export const Sfx = {
19	  jump: 'sfx_jump',
20	  hit: 'sfx_hit',
21	  tablet: 'sfx_tablet',
22	  armor: 'sfx_armor',
23	  victory: 'sfx_victory',
24	  defeat: 'sfx_defeat',
25	  ui: 'sfx_ui',
26	} as const;
27	export type SfxKey = (typeof Sfx)[keyof typeof Sfx];
28	
29	export const Music = {
30	  menu: 'music_menu',
31	  game: 'music_game',
32	} as const;
33	export type MusicKey = (typeof Music)[keyof typeof Music];
34	
35	// ── Note frequencies (Hz) used by the little placeholder tunes/stings ─────────
36	const C3 = 130.81;
37	const F3 = 174.61;
38	const G3 = 196.0;
39	const A3 = 220.0;
40	const C4 = 261.63;
41	const D4 = 293.66;
42	const E4 = 329.63;
43	const F4 = 349.23;
44	const G4 = 392.0;
45	const A4 = 440.0;
46	const B4 = 493.88;
47	const C5 = 523.25;
48	const E5 = 659.25;
49	const G5 = 783.99;
50	const B5 = 987.77;
51	const C6 = 1046.5;
52	
53	const SFX_SR = 44100; // short, crisp
54	const MUSIC_SR = 22050; // longer loops — half rate keeps the blobs small
55	
56	// ── Oscillators ──────────────────────────────────────────────────────────────
57	type WaveType = 'sine' | 'square' | 'triangle' | 'saw' | 'noise';
58	
59	function waveSample(type: WaveType, phase: number): number {
60	  const p = phase - Math.floor(phase); // wrap to [0,1)
61	  switch (type) {
62	    case 'sine':
63	      return Math.sin(p * Math.PI * 2);
64	    case 'square':
65	      return p < 0.5 ? 1 : -1;
66	    case 'triangle':
67	      return 4 * Math.abs(p - 0.5) - 1;
68	    case 'saw':
69	      return 2 * p - 1;
70	    case 'noise':
71	      return Math.random() * 2 - 1;
72	    default:
73	      return 0;
74	  }
75	}
76	
77	/** A percussive tone: fast attack, power-curve decay, optional pitch glide. */
78	interface ToneOpts {
79	  start: number;
80	  dur: number;
81	  freq: number;
82	  freqEnd?: number;
83	  type?: WaveType;
84	  gain?: number;
85	  attack?: number;
86	  decayPow?: number;
87	}
88	
89	function addTone(buf: Float32Array, sr: number, o: ToneOpts): void {
90	  const type = o.type ?? 'sine';
91	  const gain = o.gain ?? 0.3;
92	  const attack = o.attack ?? 0.005;
93	  const decayPow = o.decayPow ?? 2;
94	  const freqEnd = o.freqEnd ?? o.freq;
95	  const n0 = Math.max(0, Math.floor(o.start * sr));
96	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
97	  let phase = 0;
98	  for (let i = n0; i < n1; i++) {
99	    const t = (i - n0) / sr;
100	    const u = t / o.dur;
101	    const f = o.freq + (freqEnd - o.freq) * u;
102	    phase += f / sr;
103	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
104	    const env = a * Math.pow(1 - u, decayPow);
105	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
106	  }
107	}
108	
109	/** A sustained pad: attack/release ramps with an optional gentle vibrato. */
110	interface PadOpts {
111	  start: number;
112	  dur: number;
113	  freq: number;
114	  type?: WaveType;
115	  gain?: number;
116	  attack?: number;
117	  release?: number;
118	  vibratoHz?: number;
119	  vibratoDepth?: number;
120	}
121	
122	function addPad(buf: Float32Array, sr: number, o: PadOpts): void {
123	  const type = o.type ?? 'sine';
124	  const gain = o.gain ?? 0.2;
125	  const attack = o.attack ?? 0.02;
126	  const release = o.release ?? 0.08;
127	  const vibratoHz = o.vibratoHz ?? 0;
128	  const vibratoDepth = o.vibratoDepth ?? 0;
129	  const n0 = Math.max(0, Math.floor(o.start * sr));
130	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
131	  let phase = 0;
132	  for (let i = n0; i < n1; i++) {
133	    const t = (i - n0) / sr;
134	    const rem = o.dur - t;
135	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
136	    const r = release > 0 ? Math.min(rem / release, 1) : 1;
137	    const env = Math.max(0, Math.min(a, r));
138	    const vib = vibratoHz > 0 ? 1 + vibratoDepth * Math.sin(t * vibratoHz * Math.PI * 2) : 1;
139	    phase += (o.freq * vib) / sr;
140	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
141	  }
142	}
143	
