12	/**
13	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
14	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
15	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
16	 */
17	export class ResultsScene extends Phaser.Scene {
18	  constructor() {
19	    super({ key: SceneKey.Results });
20	  }
21	
22	  create(data: Partial<FinishGameParams> = {}): void {
23	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
24	    // default to a Game-Over result and a zero score.
25	    const win = data.result === 'win';
26	    const score = typeof data.score === 'number' ? data.score : 0;
27	    const cx = GAME_WIDTH / 2;
28	
29	    // The gameplay loop already stops its music on run-end; this is a defensive
30	    // stop for any entry path (deep-link / hot reload) so Results is silent.
31	    stopMusic();
32	
33	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
34	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
35	
36	    this.add
37	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
38	        fontFamily: 'system-ui, sans-serif',
39	        fontSize: '48px',
40	        fontStyle: 'bold',
41	        color: '#20272e',
42	      })
43	      .setOrigin(0.5);
44	
45	    this.add
46	      .text(cx, 380, t('results_score', { score }), {
47	        fontFamily: 'system-ui, sans-serif',
48	        fontSize: '30px',
49	        color: '#20272e',
50	      })
51	      .setOrigin(0.5);
52	
53	    // Promo chip + code (tap-to-copy).
54	    this.buildPromoCopyChip(cx, 460);
55	
56	    // The conversion CTA.
57	    createButton(this, {
58	      x: cx,
59	      y: 565,
60	      texture: KEYS.ui_btn_cta,
61	      label: t('results_cta'),
62	      onClick: () => this.onBuy(),
63	    });
64	
65	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
66	    createButton(this, {
67	      x: cx,
68	      y: 660,
69	      texture: KEYS.ui_btn_play_again,
70	      label: t('results_play_again'),
71	      onClick: () => {
72	        playSfx(this, Sfx.ui);
73	        this.scene.start(SceneKey.Game);
74	      },
75	    });
76	
77	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop. The
78	    // vertical padding grows the tap target to ~48px tall for touch a11y (§10.4).
79	    this.add
80	      .text(90, 44, `← ${t('results_menu')}`, {
81	        fontFamily: 'system-ui, sans-serif',
82	        fontSize: '22px',
83	        color: '#20272e',
84	        padding: { y: 12 },
85	      })
86	      .setOrigin(0, 0.5)
87	      .setInteractive({ useHandCursor: true })
88	      .on(Phaser.Input.Events.POINTER_UP, () => {
89	        playSfx(this, Sfx.ui);
90	        this.scene.start(SceneKey.Menu);
91	      });
92	  }
93	
94	  private buildPromoCopyChip(x: number, y: number): void {
95	    const container = this.add.container(x, y);
96	    const chip = this.add.image(0, 0, KEYS.ui_promo_chip).setOrigin(0.5);
97	    const text = this.add
98	      .text(0, 0, `${t('results_promo_label')} ${ENV.promoCode}`, {
99	        fontFamily: 'monospace',
100	        fontSize: '26px',
101	        fontStyle: 'bold',
102	        color: '#20272e',
103	      })
104	      .setOrigin(0.5);
105	    container.add([chip, text]);
106	    container.setSize(400, 100);
107	    container.setInteractive(
108	      new Phaser.Geom.Rectangle(-200, -50, 400, 100),
109	      Phaser.Geom.Rectangle.Contains,
110	    );
111	    if (container.input) container.input.cursor = 'pointer';
112	    container.on(Phaser.Input.Events.POINTER_UP, () => this.copyPromoCode());
113	  }
114	
115	  private async copyPromoCode(): Promise<void> {
116	    try {
117	      if (!navigator.clipboard) {
118	        return; // feature unavailable, silent no-op
119	      }
120	      await navigator.clipboard.writeText(ENV.promoCode);
121	      playSfx(this, Sfx.ui);
122	      this.showCopyConfirmation();
123	    } catch {
124	      // copy failed (e.g., no permission), silent no-op
125	      return;
126	    }
127	  }
128	
129	  private showCopyConfirmation(): void {
130	    const cx = GAME_WIDTH / 2;
131	    const label = this.add
132	      .text(cx, 410, t('results_promo_copied'), {
133	        fontFamily: 'system-ui, sans-serif',
134	        fontSize: '16px',
135	        fontStyle: 'bold',
136	        color: '#6cc04a',
137	      })
138	      .setOrigin(0.5)
139	      .setAlpha(1);
140	    this.tweens.add({
141	      targets: label,
142	      alpha: 0,
143	      duration: PROMO_COPY_FADE_MS,
144	      ease: 'Quad.in',
145	      onComplete: () => label.destroy(),
146	    });
147	  }
148	
149	  private onBuy(): void {
150	    playSfx(this, Sfx.ui);
151	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
152	    window.open(buildBuyUrl(), '_blank', 'noopener');
153	  }
154	}
