1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { ASSET_MANIFEST } from '../config/assetManifest';
4	import { t } from '../i18n/strings';
5	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
6	import { registerAudio } from '../systems/audio';
7	
8	/**
9	 * PreloadScene — loads EVERY asset from the shared manifest (as SVGs at their
10	 * logical sizes) behind a loading bar, then advances to the menu. Nothing
11	 * critical is lazy-loaded (spec §10.5). (Audio unlock is installed once in
12	 * BootScene on a long-lived window listener, not here.)
13	 */
14	export class PreloadScene extends Phaser.Scene {
15	  constructor() {
16	    super({ key: SceneKey.Preload });
17	  }
18	
19	  preload(): void {
20	    this.buildLoadingBar();
21	
22	    // Fail LOUD if any manifest key is missing on disk (e.g. a new key added to
23	    // assetManifest.ts without regenerating placeholders → a silent 404). This
24	    // is a real error path, not log spam.
25	    this.load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, (file: Phaser.Loader.File) => {
26	      console.error(`[assets] failed to load "${file.key}" from ${file.src} — is the SVG present?`);
27	    });
28	
29	    // The manifest is the single source of truth: iterate & load each SVG.
30	    // Manifest paths are base-relative (`assets/<group>/<key>.svg`); Vite does NOT
31	    // rewrite these runtime strings, so prefix `import.meta.env.BASE_URL` (=
32	    // `/HappyDog/` in prod, `/` in dev) so every SVG resolves under the deploy
33	    // sub-path instead of 404-ing at the domain root.
34	    const base = import.meta.env.BASE_URL;
35	    for (const a of ASSET_MANIFEST) {
36	      this.load.svg(a.key, `${base}${a.path}`, { width: a.width, height: a.height });
37	    }
38	
39	    // Placeholder SFX/music: synthesized to WAV blobs at runtime and queued onto
40	    // this same loader (no external files / network — 100% static-hostable).
41	    registerAudio(this);
42	  }
43	
44	  create(): void {
45	    this.scene.start(SceneKey.Menu);
46	  }
47	
48	  private buildLoadingBar(): void {
49	    const cx = GAME_WIDTH / 2;
50	    const cy = GAME_HEIGHT / 2;
51	    const barW = 520;
52	    const barH = 26;
53	
54	    this.add
55	      .text(cx, cy - 48, t('loading'), {
56	        fontFamily: 'system-ui, sans-serif',
57	        fontSize: '22px',
58	        color: '#f4f7fa',
59	      })
60	      .setOrigin(0.5);
61	
62	    const frame = this.add.graphics();
63	    frame.lineStyle(2, 0x5b6670, 1);
64	    frame.strokeRect(cx - barW / 2, cy - barH / 2, barW, barH);
65	
66	    const fill = this.add.graphics();
67	    const pct = this.add
68	      .text(cx, cy + 40, '0%', {
69	        fontFamily: 'system-ui, sans-serif',
70	        fontSize: '16px',
71	        color: '#9fb0bd',
72	      })
73	      .setOrigin(0.5);
74	
75	    this.load.on(Phaser.Loader.Events.PROGRESS, (value: number) => {
76	      fill.clear();
77	      fill.fillStyle(0x6cc04a, 1);
78	      fill.fillRect(cx - barW / 2 + 3, cy - barH / 2 + 3, (barW - 6) * value, barH - 6);
79	      pct.setText(`${Math.round(value * 100)}%`);
80	    });
81	  }
82	}
