1	/**
2	 * track.ts — the SINGLE analytics choke point (spec §7.1).
3	 *
4	 * Game code never touches gtag/fbq directly; it calls the typed `track()`
5	 * overloads, which fan out to GA4 (gtag) and Meta Pixel (fbq) with the EXACT
6	 * event names + param shapes from spec §7.2:
7	 *   GA4:   gtag('event', <name>, <params>)
8	 *   Pixel: fbq('trackCustom', <name>, <params>)
9	 *
10	 * Everything here is SAFE when the pixels are absent/blocked/misconfigured:
11	 *  - Vendor scripts are injected at runtime by initAnalytics(), and ONLY when a
12	 *    real (non-empty, non-placeholder) ID is present — so with no `.env` (dev,
13	 *    previews) nothing loads and no network request is made.
14	 *  - Every dispatch is `typeof`-guarded, so a missing gtag/fbq global never throws.
15	 *  - A consent gate wraps both loading AND dispatch (spec §7.4).
16	 */
17	
18	import { ENV } from '../config/env';
19	
20	declare global {
21	  interface Window {
22	    gtag?: (...args: unknown[]) => void;
23	    fbq?: ((...args: unknown[]) => void) & { callMethod?: (...args: unknown[]) => void };
24	    dataLayer?: unknown[];
25	    _fbq?: unknown;
26	  }
27	}
28	
29	/** The three funnel events — names are FIXED by the brief (§3B); do not rename. */
30	export type AnalyticsEvent = 'start_game' | 'finish_game' | 'click_buy';
31	
32	/** `start_game` — a round begins. No params required (spec §7.2). */
33	export type StartGameParams = Record<string, never>;
34	
35	/** `finish_game` — a round ends (win OR lose) (spec §7.2). */
36	export interface FinishGameParams {
37	  result: 'win' | 'lose';
38	  score: number;
39	  /** Active play time in seconds, EXCLUDING paused time. */
40	  duration_s: number;
41	}
42	
43	/** `click_buy` — the results-screen CTA was tapped (spec §7.2). */
44	export interface ClickBuyParams {
45	  destination: string;
46	  promo_code: string;
47	}
48	
49	// ── Config guard (treats empty AND example placeholders as "not configured") ──
50	// The .env.example ships illustrative placeholders (G-XXXXXXXXXX, an all-zero
51	// pixel id). If someone copies it verbatim, analytics must stay a safe no-op —
52	// so we reject empty strings and any obvious placeholder shape here.
53	function isConfigured(id: string | undefined): boolean {
54	  const v = (id ?? '').trim().toLowerCase();
55	  if (v === '') return false;
56	  if (/^g-x+$/.test(v)) return false; // GA4 placeholder, e.g. G-XXXXXXXXXX
57	  if (/^x+$/.test(v)) return false; // generic all-X placeholder
58	  if (/^0+$/.test(v)) return false; // all-zero pixel id, e.g. 000000000000000
59	  return true;
60	}
61	
62	// ── Consent gate (spec §7.4) ───────────────────────────────────────────────
63	// The adapter ships "consent-ready": a single flag every event passes through.
64	// A future CMP flips it via setAnalyticsConsent(); until then it defaults to
65	// granted so the funnel is observable in dev/QA. Vendor scripts are only loaded
66	// (and events only dispatched) while consent is granted.
67	let consentGranted = true;
68	
69	export function setAnalyticsConsent(granted: boolean): void {
70	  consentGranted = granted;
71	  // A deferred grant (e.g. a CMP banner accepted after boot) should still bring
72	  // the vendors up — initAnalytics() is idempotent, so this is safe to re-call.
73	  if (granted) initAnalytics();
74	}
75	
76	function hasConsent(): boolean {
77	  return consentGranted;
78	}
79	
80	// ── track() — typed overloads so call sites get the right param shape ──────
81	export function track(event: 'start_game', params?: StartGameParams): void;
82	export function track(event: 'finish_game', params: FinishGameParams): void;
83	export function track(event: 'click_buy', params: ClickBuyParams): void;
84	// Implementation signature: `object` is the loosest supertype of every event's
85	// param shape (interfaces aren't assignable to Record<string, unknown> in TS).
86	export function track(event: AnalyticsEvent, params: object = {}): void {
87	  if (!hasConsent()) return;
88	
89	  // GA4 — one custom event per funnel step (spec §7.2). `typeof` guard so an
90	  // absent/blocked gtag never throws.
91	  if (typeof window.gtag === 'function') {
92	    window.gtag('event', event, params);
93	  }
94	  // Meta Pixel — the brief's three names are CUSTOM events (trackCustom), not
95	  // Meta standard events (spec §7.3). `typeof` guard for the same reason.
96	  if (typeof window.fbq === 'function') {
97	    window.fbq('trackCustom', event, params);
98	  }
99	
100	  if (ENV.debugAnalytics) {
101	    // Intentional QA mirror, gated behind VITE_DEBUG_ANALYTICS.
102	    console.debug('[track]', event, params);
103	  }
104	}
105	
106	// ── initAnalytics() — env-gated loader (called once from main.ts) ──────────
107	// Injects the GA4 / Pixel bootstraps ONLY when a real ID is present AND consent
108	// is granted. With no IDs (dev/preview) or placeholder IDs this is a no-op and
109	// track() stays safe. Idempotent: safe to call again after a deferred consent.
110	let ga4Loaded = false;
111	let pixelLoaded = false;
112	
113	export function initAnalytics(): void {
114	  if (!hasConsent()) return;
115	
116	  if (!ga4Loaded && isConfigured(ENV.ga4Id)) {
117	    ga4Loaded = true;
118	    loadGa4(ENV.ga4Id);
119	  }
120	  if (!pixelLoaded && isConfigured(ENV.fbPixelId)) {
121	    pixelLoaded = true;
122	    loadPixel(ENV.fbPixelId);
123	  }
124	}
125	
126	function loadGa4(measurementId: string): void {
127	  const s = document.createElement('script');
128	  s.async = true;
129	  s.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(measurementId)}`;
130	  document.head.appendChild(s);
131	
132	  window.dataLayer = window.dataLayer ?? [];
133	  const gtag: (...args: unknown[]) => void = (...args) => {
134	    window.dataLayer?.push(args);
135	  };
136	  window.gtag = gtag;
137	  gtag('js', new Date());
138	  gtag('config', measurementId);
139	}
140	
141	function loadPixel(pixelId: string): void {
142	  if (!window.fbq) {
143	    const fbq = ((...args: unknown[]) => {
144	      fbq.callMethod ? fbq.callMethod(...args) : fbq.queue.push(args);
145	    }) as ((...args: unknown[]) => void) & {
146	      callMethod?: (...args: unknown[]) => void;
147	      queue: unknown[][];
148	      loaded: boolean;
149	      version: string;
150	    };
151	    fbq.queue = [];
152	    fbq.loaded = true;
153	    fbq.version = '2.0';
154	    window.fbq = fbq;
155	    window._fbq = window._fbq ?? fbq;
156	
157	    const s = document.createElement('script');
158	    s.async = true;
159	    s.src = 'https://connect.facebook.net/en_US/fbevents.js';
160	    document.head.appendChild(s);
161	  }
162	  window.fbq('init', pixelId);
163	  window.fbq('track', 'PageView');
164	}
