300	interface AudioDef {
301	  readonly key: string;
302	  readonly sr: number;
303	  readonly make: () => Float32Array;
304	}
305	
306	const AUDIO_DEFS: readonly AudioDef[] = [
307	  { key: Sfx.jump, sr: SFX_SR, make: makeJump },
308	  { key: Sfx.hit, sr: SFX_SR, make: makeHit },
309	  { key: Sfx.tablet, sr: SFX_SR, make: makeTablet },
310	  { key: Sfx.armor, sr: SFX_SR, make: makeArmor },
311	  { key: Sfx.victory, sr: SFX_SR, make: makeVictory },
312	  { key: Sfx.defeat, sr: SFX_SR, make: makeDefeat },
313	  { key: Sfx.ui, sr: SFX_SR, make: makeUi },
314	  { key: Music.menu, sr: MUSIC_SR, make: makeMenuMusic },
315	  { key: Music.game, sr: MUSIC_SR, make: makeGameMusic },
316	];
317	
318	// Object URLs for the synthesized WAV blobs. Created lazily as each sound is
319	// queued onto the loader and revoked once Phaser has decoded them, so they don't
320	// leak for the page's lifetime.
321	const blobUrls = new Map<string, string>();
322	
323	function audioUrl(def: AudioDef): string {
324	  let url = blobUrls.get(def.key);
325	  if (!url) {
326	    url = wavUrl(def.make(), def.sr);
327	    blobUrls.set(def.key, url);
328	  }
329	  return url;
330	}
331	
332	/** Queue every placeholder sound onto the scene's loader (call from PreloadScene). */
333	export function registerAudio(scene: Phaser.Scene): void {
334	  let queued = 0;
335	  for (const def of AUDIO_DEFS) {
336	    if (scene.cache.audio.exists(def.key)) continue; // already loaded — idempotent
337	    scene.load.audio(def.key, audioUrl(def));
338	    queued++;
339	  }
340	  if (queued === 0) return;
341	
342	  // Free the object URLs once loading finishes. Under Web Audio (the default),
343	  // Phaser decodes each WAV from an in-memory ArrayBuffer BEFORE the file is
344	  // marked complete (AudioFile.onProcess resolves decodeAudioData first), and the
345	  // blob URL was only ever the XHR source — so revoking on COMPLETE cannot break
346	  // playback. Under the HTML5 Audio fallback the <audio> elements keep pointing at
347	  // the URL, so we leave those alive (bounded, session-lived — not a growing leak).
348	  scene.load.once(Phaser.Loader.Events.COMPLETE, () => {
349	    if (scene.sound instanceof Phaser.Sound.WebAudioSoundManager) {
350	      revokeAudioUrls();
351	    }
352	  });
353	}
354	
355	/** Revoke every synthesized-WAV object URL. Safe once Web Audio has decoded them. */
356	export function revokeAudioUrls(): void {
357	  for (const url of blobUrls.values()) URL.revokeObjectURL(url);
358	  blobUrls.clear();
359	}
360	
361	// ── Playback (mute is enforced globally by the shared sound manager) ──────────
362	export function playSfx(scene: Phaser.Scene, key: SfxKey): void {
363	  const volume = key === Sfx.ui ? AUDIO.uiVolume : AUDIO.sfxVolume;
364	  scene.sound.play(key, { volume });
365	}
366	
367	// Single looping music track shared across scenes (the sound manager is global).
368	let currentMusic: Phaser.Sound.BaseSound | undefined;
369	let currentMusicKey: MusicKey | undefined;
370	
371	export function playMusic(scene: Phaser.Scene, key: MusicKey): void {
372	  if (currentMusicKey === key && currentMusic && (currentMusic.isPlaying || currentMusic.isPaused)) {
373	    return; // already the active track — don't restart or stack
374	  }
375	  stopMusic();
376	  const music = scene.sound.add(key, { loop: true, volume: AUDIO.musicVolume });
377	  music.play();
378	  currentMusic = music;
379	  currentMusicKey = key;
380	}
381	
382	export function stopMusic(): void {
383	  if (currentMusic) {
384	    currentMusic.stop();
385	    currentMusic.destroy();
386	  }
387	  currentMusic = undefined;
388	  currentMusicKey = undefined;
389	}
390	
391	export function pauseMusic(): void {
392	  if (currentMusic && currentMusic.isPlaying) currentMusic.pause();
393	}
394	
395	export function resumeMusic(): void {
396	  if (currentMusic && currentMusic.isPaused) currentMusic.resume();
397	}
